/**
 * Generated by scaffold-fixtures-per-entity. Inserts a Enrollment row
 * directly via the repository. Useful for tests that need a pre-seeded record
 * without going through the full HTTP create flow.
 */
import { DataSource } from 'typeorm';

export interface CreateEnrollmentInput {
  [key: string]: unknown;
}

export async function createTestEnrollment(
  dataSource: DataSource,
  overrides: CreateEnrollmentInput = {},
): Promise<Record<string, unknown>> {
  const meta = dataSource.entityMetadatas.find(
    (m) => m.name === 'Enrollment' || m.tableName === 'enrollments',
  );
  if (!meta) {
    throw new Error('createTestEnrollment: Enrollment entity not registered with the DataSource');
  }
  const repo = dataSource.getRepository(meta.target);
  const row: Record<string, unknown> = {
    status: 'test-status',
    progressPercent: 0,
    enrolledAt: new Date(),
    completedAt: new Date(),
    ...overrides,
  };
  const saved = await repo.save(row as never);
  return saved as unknown as Record<string, unknown>;
}
